<style>
/* Kids has its own visual language; loaded after the church theme intentionally. */
html:has(body.kids){background:#f4f4fc;color-scheme:light}
body.kids{--parchment:#f4f4fc;--cream:#eeeafa;--ink:#272541;--ink-soft:#625e79;--ink-faint:#807b95;--line:#dedbed;--teal:#6448cf;--teal-dark:#4931a5;--brass:#ae7017;--green:#157358;--red:#b94462;background:#f4f4fc;color:#272541;font-family:'Nunito',system-ui,sans-serif;letter-spacing:0}
.kids h1,.kids h2,.kids .t,.kids .tb-title{font-family:'Outfit','Nunito',sans-serif!important;font-style:normal;font-weight:700;letter-spacing:-.035em;color:var(--ink)}
.kids button,.kids input,.kids .small,.kids .mcard,.kids .cbtn small{font-family:'Nunito',system-ui,sans-serif!important}
.kids *:focus-visible{outline:3px solid #bc7920;outline-offset:4px}
.kids .btn{display:inline-flex;align-items:center;justify-content:center;gap:18px;background:#6448cf;color:#fff!important;border:2px solid #6448cf;border-radius:16px;box-shadow:0 4px 0 #45308e;font-size:15px;font-weight:900;line-height:1.3;padding:14px 23px;text-decoration:none;transition:transform .18s,box-shadow .18s;letter-spacing:0;text-transform:none}
.kids .btn:hover{background:#5539ba;border-color:#5539ba;color:white!important;transform:translateY(-2px);box-shadow:0 6px 0 #45308e}
.kids .btn:active{transform:translateY(3px);box-shadow:0 1px 0 #45308e}
.kids .btn.btn-ghost{background:#eeeafa;color:#49349a!important;border:2px solid #dfd7f8;box-shadow:none}
.kids .btn.btn-ghost:hover{background:#e2d9fc;color:#342175!important;border-color:#c6b8ee}
.kids button[hidden]{display:none!important}
.kids .eyebrow,.kids .genre-tag,.kids .game-kicker{font-size:10px;letter-spacing:.16em;font-weight:900;color:#6755a1;margin:0 0 12px;text-transform:uppercase}
.kids-index main{max-width:1180px;padding:36px 30px 70px}
.adventure-hero{display:grid;grid-template-columns:1fr 1fr;overflow:hidden;background:#e8e4fb;border-radius:32px;position:relative;min-height:410px;border:1px solid #e1dbf3}
.hero-copy{padding:46px 38px;z-index:1;align-self:center}.kids .hero-copy h1{font-size:clamp(38px,4.6vw,60px);line-height:1.04}.hero-copy h1 span{color:#654bc8}.kids .hero-copy .lede{font-size:17px;line-height:1.55;max-width:330px;margin-top:20px}.hero-copy .btn{margin-top:25px}.hero-copy .who{font-size:12px;margin-top:20px}.hero-art{width:100%;height:100%;object-fit:cover;object-position:64% center;min-width:0}
.catalog-heading{display:flex;align-items:end;justify-content:space-between;gap:20px;margin:48px 0 20px;scroll-margin-top:24px}.catalog-heading h2{font-size:30px}.catalog-heading p{font-size:13px;color:var(--ink-soft);max-width:220px}.catalog-heading .eyebrow{margin-bottom:7px}
.kids .filters{margin:0 0 30px;gap:8px}.kids .chip{background:white;color:#57516b;border:1px solid #dedbed;border-radius:12px;padding:11px 18px;font-size:13px;font-weight:800}.kids .chip.on{background:#30294e;color:white;border-color:#30294e}
.kids .sec{padding:26px;border-radius:26px;margin-top:24px;background:#ebe6fb;border:1px solid #ded5f5;--genre:#6448cf}.kids .genre-hidden_words{background:#e5f3ea;border-color:#cde7d6;--genre:#237451}.kids .genre-word_search{background:#e4effa;border-color:#cadff3;--genre:#26628f}.kids .genre-verse_tetris{background:#26243e;border-color:#393452;--genre:#c0b3ff}.kids .genre-verse_tetris h2,.kids .genre-verse_tetris .genre-tag{color:#eeeaff}.kids .genre-verse_tetris .sub{color:#c4bddd}
.genre-head{display:flex;gap:26px;align-items:center}.kids .sec h2{font-size:30px;line-height:1.1}.kids .sec .sub{font-size:14px;line-height:1.5;max-width:480px;margin-top:8px}.kids .genre-tag{color:var(--genre);margin-bottom:7px;font-size:9px}
.game-preview{position:relative;flex:0 0 145px;height:118px;overflow:hidden;border-radius:20px;background:#d6cafa;display:grid;place-items:center}.genre-hidden_words .game-preview{background:#bce0c7}.genre-word_search .game-preview{background:#b9d6f4}.genre-verse_tetris .game-preview{background:#191a30}
.mini-card{position:absolute;width:58px;height:76px;border-radius:12px;border:3px solid #fff;box-shadow:0 8px 0 #45308e30;left:38px;top:19px}.back-card{transform:rotate(-18deg) translateX(-17px);background:repeating-linear-gradient(45deg,#7d5bd5 0 9px,#8869dc 9px 18px)}.face-card{transform:rotate(14deg) translateX(16px);background:#fff;color:#dd5681;padding:8px;display:grid;place-items:center}.face-card svg{width:44px;height:44px}.art-dot{position:absolute;border-radius:50%;width:9px;height:9px;background:#f8c75c}.dot-one{right:17px;top:20px}.dot-two{left:16px;bottom:17px}.mini-search{display:grid;grid-template-columns:repeat(3,25px);gap:3px;transform:rotate(-8deg);padding:8px;background:white;border-radius:12px;box-shadow:0 7px 0 #698eb359}.mini-search span{display:grid;place-items:center;font:800 16px 'Outfit';height:25px;color:#3a628a;border-radius:5px}.mini-search span:nth-child(-n+3){background:#598ccd;color:white}.mini-trail{display:flex;gap:5px;align-items:center;transform:rotate(-20deg)}.mini-trail i{width:19px;height:14px;border-radius:50%;background:#fff9d9;box-shadow:0 4px #77b58b}.mini-trail i:nth-child(2){margin-top:22px}.mini-trail b{font-size:47px;color:#d39414;text-shadow:0 3px #a8740f}.mini-blocks{display:grid;grid-template-columns:repeat(3,24px);gap:3px;transform:rotate(-13deg)}.mini-blocks i{height:24px;background:#9675ec;box-shadow:inset 3px 3px #c1a6ff,inset -3px -4px #6841bc,3px 5px 0 #110f23;border-radius:5px}.mini-blocks i:nth-child(3n){background:#f1a349;box-shadow:inset 3px 3px #ffd28f,inset -3px -4px #a36625,3px 5px #110f23}.mini-blocks i:first-child{visibility:hidden}
.kids .grid{grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px;margin-top:24px}.kids .lvl{border:none;border-radius:17px;padding:19px;background:#ffffffef;box-shadow:0 3px 0 #2823430b}.kids .lvl .ref{color:#6d628e;font-size:9px;letter-spacing:.09em;font-weight:900}.kids .lvl .t{font-size:21px;margin-top:8px;line-height:1.15}.kids .lvl .bk{font-size:11px;margin-top:9px;color:#6b647e}.kids .lvl .go{display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#5942af;margin-top:17px;font-weight:900}.kids .lvl:hover{transform:translateY(-4px);box-shadow:0 8px 0 #28234312}.kids-index .board{background:white;border:1px solid #dedbed;border-radius:22px;margin-top:28px}.kids-index .board h2{font-size:25px}.kids .family-note{font-size:12px;max-width:680px}.kids .family-note a{color:#5942af}
/* Play space */
.kids-play{background:radial-gradient(ellipse at 12% 30%,#e5dcfa 0,transparent 45%),radial-gradient(ellipse at 90% 70%,#e0f0eb 0,transparent 40%),#f5f4fb!important}.kids .top{border:0;max-width:1080px;margin:auto;padding:22px 26px}.kids .top a{font-size:12px;font-weight:900;color:#514578;letter-spacing:0;text-transform:none;display:flex;gap:8px;align-items:center}.kids .who{font-size:12px;color:#665c80}.kids-play main{max-width:760px;padding:12px 24px 45px}.kids-play h1{font-size:clamp(28px,5vw,41px);margin:8px 0 0;line-height:1.1}.kids-play .ref{font-size:11px;letter-spacing:.05em;font-weight:800;color:#716782}.kids-play .game-kicker{margin-bottom:9px;color:#6247ba}.kids .journey{max-width:440px;margin-top:22px;font-size:12px;color:#66578b}.kids progress{height:11px;margin-top:9px;border-radius:20px}.kids progress::-webkit-progress-bar{background:#e1daef}.kids progress::-webkit-progress-value{background:linear-gradient(90deg,#9c81ef,#6548ca);border-radius:20px;transition:width .35s}.kids .tools{margin-top:15px;gap:8px}.kids .tools button{border:1px solid #dfd8ef;background:#fff;color:#574584;font-size:12px;font-weight:800;border-radius:12px;padding:10px 14px}.kids .hint{font-size:13px;line-height:1.6;max-width:490px;margin:16px auto 0;color:#635b77}.kids .feedback{font-size:14px;font-weight:900;color:#5d458f;min-height:23px;margin-top:20px}
.kids .mm{max-width:470px;gap:12px;margin-top:24px}.kids .mcard{position:relative;aspect-ratio:1.12;border:3px solid #8060d7;border-radius:20px;background:linear-gradient(140deg,#9473e5,#6948bf);box-shadow:0 6px 0 #513695,0 9px 16px #624a9726;color:white;font-size:15px;font-weight:900;transition:transform .2s,box-shadow .2s}.kids .mcard:hover:not(:disabled){transform:translateY(-3px);box-shadow:0 9px 0 #513695,0 14px 20px #624a9726}.mcard .q{display:grid;place-items:center;width:60%;aspect-ratio:1;border:1px solid #ffffff30;border-radius:50%;background:#ffffff0e}.mcard .q svg{width:60%;color:#fff7}.kids .mcard.up,.kids .mcard.done{background:#fff;color:#383047;border-color:#fff;font-size:clamp(10px,2.6vw,14px);box-shadow:0 5px 0 #dcd6ea}.kids .mcard .icon{height:43px;margin:0 auto 6px;color:var(--card-color);font-size:inherit}.mcard .icon svg{height:100%;width:50px}.kids .mcard.done{background:#f0fbf3;border-color:#b9dec5;box-shadow:0 5px 0 #99c3a7}.mcard.done:after{content:'✓';position:absolute;right:7px;top:3px;font-size:13px;color:#217846}.kids .ws{padding:12px;background:white;border:1px solid #e0dbee;border-radius:22px;box-shadow:0 7px 0 #e0daed;margin-top:22px}.kids .cell{background:#f4f1fc;border:0;border-radius:7px;color:#4a3a69;font-weight:900;box-shadow:none}.kids .cell.found{background:#7256cf;color:#fff}.kids .cell.sel{background:#ddbc62;color:#362953}.kids .cell.hinted{outline:3px solid #b47a16;background:#fff0ba}.kids .word{font-size:12px;border:0;padding:8px 13px;background:#e6e0f5;color:#594981}.kids .word.got{background:#d5eddd;color:#276042;text-decoration:none}.kids .word.got:before{content:'✓ ';font-weight:900}
.trail-scene{height:160px;max-width:500px;margin:22px auto 0;background:url('/kids-assets/adventure-world-v1.jpg') 50% 48%/cover;border-radius:24px;position:relative;overflow:hidden;box-shadow:0 6px 0 #d6e3da}.trail-scene:after{content:'';position:absolute;bottom:27px;left:8%;right:8%;border-top:7px dotted #fff8b7}.trail-marker{position:absolute;z-index:1;bottom:15px;left:8%;width:30px;height:30px;background:#ffc84a;border:4px solid #fff4c6;border-radius:50%;box-shadow:0 3px 0 #996815;transition:left .5s}.trail-clue{font-size:19px;font-weight:900;margin:22px 0 13px;color:#4e4068}.trail-choices{display:flex;justify-content:center;gap:10px;flex-wrap:wrap}.kids .word-choice{border:2px solid #d1c6e6;box-shadow:0 4px #d1c6e6;background:#fff;color:#554279;font:900 18px 'Nunito';border-radius:15px;min-width:85px;padding:13px 17px}.kids .word-choice:hover{background:#eee7fb}.kids .word-choice.correct{background:#d5eddd;border-color:#64a57b}.kids .word-choice.try-again{background:#f9eee0;border-color:#d4a979}.kids .hw{gap:7px;margin-top:24px}.kids .htile{padding:5px 9px;border:0;background:transparent;font-size:16px;color:#9c90b4;min-width:22px}.kids .htile.on{background:#e5e0f1;color:#483765;border:none}
/* Dialogs: clear hierarchy and explicit contrast in every button state. */
.kids .ov{background:#17112899;backdrop-filter:blur(8px);padding:20px}.kids .card{background:#fff;border:1px solid #eee8f8;border-radius:30px;padding:30px;max-width:450px;box-shadow:0 28px 100px #160c4c40;max-height:calc(100dvh - 40px);overflow:auto;color:#272541}.kids .card h2{font-size:30px;line-height:1.1;color:#302746}.kids .card p{font-size:14px;color:#6d637e;margin-top:12px;line-height:1.5}.kids .card .small{font-size:11px!important;line-height:1.6!important;color:#706780}.kids .card input{background:#f7f5fc;border:2px solid #ded5ef;border-radius:14px;color:#332747;font-weight:800;font-size:17px}.kids .card .btn{width:100%;margin-top:14px}.kids .card .verse,.kids .verse-final{font-family:'Nunito',sans-serif;font-style:normal;font-weight:700;font-size:17px;line-height:1.5;color:#514063;background:#f2eef9;border-radius:16px;padding:18px;margin:20px 0 6px}.verse small{display:block;font-size:10px;font-weight:900;letter-spacing:.12em;text-transform:uppercase;color:#847194;margin-bottom:7px}.kids .stars-big{font:900 10px 'Nunito';text-transform:uppercase;letter-spacing:.15em;color:#8b6b25;margin:14px 0 9px}.kids .stars-big.preview{font:900 10px 'Nunito';letter-spacing:.12em}.win-art{display:flex;justify-content:center;gap:10px;align-items:center;height:80px}.win-spark{font:70px/1 system-ui;color:#f1bd43;text-shadow:0 5px #c68b22,0 9px 20px #e7b84c50;transform:rotate(-12deg)}.win-spark:nth-child(2){font-size:90px;transform:translateY(-5px)}.win-spark:nth-child(3){transform:rotate(12deg)}.ov.show .win-spark{animation:star-arrive .6s cubic-bezier(.2,1.5,.5,1) both}.ov.show .win-spark:nth-child(2){animation-delay:.12s}.ov.show .win-spark:nth-child(3){animation-delay:.24s}@keyframes star-arrive{from{opacity:0;scale:.3}to{opacity:1;scale:1}}.kids .replay-link{display:block;margin:20px auto 0;padding:7px 10px;border:0;background:transparent;color:#6d5796;font-size:12px;font-weight:900;cursor:pointer}.gate-art{height:115px;background:url('/kids-assets/adventure-world-v1.jpg') 80% 62%/cover;border-radius:18px;margin-bottom:22px}.kids .small a{color:#58408e}
/* Verse Blocks: dimensional arcade cabinet, calmer perimeter. */
body.kids-tetris{--ink:#f5f1ff;--ink-soft:#c3b7df;--line:#45385f;--teal:#bda5ff;background:radial-gradient(ellipse at 50% 25%,#342349,#141225 75%);color:#f5f1ff}.kids-tetris .game{max-width:520px;padding:0 6px}.kids-tetris .topbar{border:0;padding:13px 15px}.kids-tetris .tb-title{color:#f5f1ff;font-size:20px}.kids-tetris .tb-ref{font-size:9px;letter-spacing:.1em;color:#b9a4dd}.kids-tetris .topbar a.back{color:#ddd1f4;letter-spacing:0}.kids-tetris .pausebtn{background:#3b2e55;color:#eee3ff}.arcade-hud{display:flex;align-items:center;justify-content:space-between;padding:0 18px 6px;font-size:9px;letter-spacing:.12em;font-weight:900;color:#bdaed5;flex-shrink:0}.arcade-hud>span{display:flex;align-items:center;gap:12px}.next-shape{display:grid;gap:2px;min-height:22px;align-content:center}.next-shape i{width:9px;height:9px;display:block}.kids .arcade-hud button{background:transparent;border:1px solid #5b4775;border-radius:10px;color:#dfd3ef;font-size:10px;font-weight:800;padding:7px 10px}.kids-tetris .boardarea{padding:2px 10px 10px;perspective:1000px}.kids-tetris .board{background:linear-gradient(145deg,#171325,#231b35);border:5px solid #594272;border-top-color:#8361a7;border-left-color:#765295;border-radius:16px;padding:7px;gap:3px;box-shadow:7px 8px 0 #0b0816,10px 13px 0 #35223f,0 18px 45px #0008,inset 0 3px 14px #0008}.kids-tetris .tc{background:#ffffff05;border-radius:4px}.kids-tetris .tc.c1{--bc:#37cee0}.kids-tetris .tc.c2{--bc:#f6cc55}.kids-tetris .tc.c3{--bc:#b08cff}.kids-tetris .tc.c4{--bc:#6ddaac}.kids-tetris .tc.c5{--bc:#f27e9d}.kids-tetris .tc.c6{--bc:#619ef7}.kids-tetris .tc.c7{--bc:#ffae6a}.kids-tetris .tc[class*=' c']{background:linear-gradient(145deg,color-mix(in srgb,var(--bc) 65%,white),var(--bc) 50%,color-mix(in srgb,var(--bc) 70%,black));box-shadow:inset 3px 3px 0 #ffffff55,inset -3px -4px 0 #0004,1px 2px 3px #0008;border:1px solid color-mix(in srgb,var(--bc) 60%,white);border-radius:4px}.kids-tetris .tc.ghost{border:1px solid color-mix(in srgb,var(--bc) 55%,transparent);box-shadow:inset 0 0 8px #ffffff0a!important}.kids-tetris .infobar{padding:8px 18px;gap:7px 14px;color:#bfb0d5;font-size:11px}.kids-tetris .infobar b{color:white;font:700 17px 'Outfit';margin-left:4px}.kids-tetris .who{color:#bfb0d5;font-size:10px}.kids-tetris .rmchip{background:#685092;color:white;font-size:10px;padding:8px 11px;border-radius:10px}.kids-tetris .rmchip:disabled{background:#352a47;color:#c1b1d0}.kids-tetris .versestrip{font-family:'Nunito',sans-serif;font-size:13px;color:#9584a7;border-top-color:#443450}.kids-tetris .versestrip .vw.got{color:#fff3bb}.kids-tetris .verse-progress,.kids-tetris .save-row{color:#bdaace;font-size:10px}.kids-tetris .cbtn{height:49px;background:linear-gradient(#4e3e68,#362b4b);border:1px solid #6d568c;border-bottom:4px solid #21192e;color:#f7f0ff;border-radius:12px;box-shadow:0 3px #100b1c;font-size:21px}.kids-tetris .cbtn[data-act=hard]{background:linear-gradient(#9f72d5,#724da8);border-color:#bd93ee;border-bottom-color:#472a6c}.kids-tetris .card{--ink:#272541;--ink-soft:#625e79;--teal:#6448cf;--line:#dedbed}.kids-tetris .card .ref{color:#6d519e}.kids-tetris .shp{background:#eee8f7;color:#674b95;border-color:#d8ccea}.arcade-toast{position:absolute;z-index:3;pointer-events:none;background:#fff0b7;color:#493454;font:900 16px 'Nunito';border-radius:14px;padding:13px 22px;box-shadow:0 6px 0 #b8903c;opacity:0;transform:translateY(15px);transition:.2s}.arcade-toast.show{opacity:1;transform:translateY(0)}
@media(max-width:650px){.kids-index main{padding:20px 16px 50px}.adventure-hero{grid-template-columns:1fr;border-radius:24px}.hero-copy{padding:30px 25px}.kids .hero-copy h1{font-size:43px}.hero-art{height:220px;object-position:60% 55%;grid-row:2}.hero-copy .lede{font-size:15px;max-width:300px}.hero-copy .btn{margin-top:18px}.hero-copy .who:empty{display:none}.catalog-heading{margin-top:32px;display:block}.catalog-heading h2{font-size:26px}.catalog-heading p{max-width:none;margin-top:8px}.kids .chip{padding:10px 12px;font-size:11px}.kids .filters{gap:6px}.kids .sec{padding:17px;border-radius:22px}.genre-head{gap:15px}.game-preview{flex-basis:96px;height:100px}.mini-card{left:19px;top:16px;width:50px;height:65px}.face-card svg{width:35px}.kids .sec h2{font-size:25px}.kids .sec .sub{font-size:12px}.kids .genre-tag{font-size:8px;letter-spacing:.1em}.kids .grid{grid-template-columns:1fr 1fr;gap:9px;margin-top:18px}.kids .lvl{padding:15px 12px;border-radius:14px}.kids .lvl .t{font-size:18px}.kids .lvl .bk{font-size:10px}.kids .lvl .ref{font-size:8px}.kids .lvl .go{font-size:10px}.kids .card{padding:25px 22px;border-radius:24px}.kids .card h2{font-size:27px}.kids .card .verse{font-size:16px;padding:14px}.kids-play main{padding:8px 18px 35px}.kids .top{padding:17px 20px}.kids .mm{gap:10px}.kids .mcard{border-radius:16px}.kids .mcard .icon{height:34px;margin-bottom:3px}.kids .ws{padding:8px;border-radius:17px}.kids .cell{border-radius:5px}.win-art{height:65px}.win-spark{font-size:55px}.win-spark:nth-child(2){font-size:75px}.kids .stars-big{margin-top:12px}.trail-scene{height:130px}.kids .word-choice{font-size:16px;min-width:70px}.kids-tetris .topbar{padding-top:9px}.kids-tetris .board{gap:2px;padding:5px}.kids-tetris .card p{font-size:13px}}
@media(prefers-reduced-motion:reduce){.kids *, .kids *:before,.kids *:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
</style>
<style>
.mission-note{margin:1px 18px 8px;padding:9px 12px;background:#392c4a;border:1px solid #534066;border-radius:12px;flex-shrink:0;font-size:11px;line-height:1.4;color:#e0d3ef;display:flex;gap:9px;align-items:center}.mission-note b{color:#f6db86;font-size:10px;flex-shrink:0;max-width:105px}.mission-note span{max-width:300px}.kids .take-it-with-you{text-align:left;background:#e9f4ed;border-radius:14px;padding:15px;margin-top:15px;color:#316049}.take-it-with-you>b{font-size:9px;letter-spacing:.1em}.kids .take-it-with-you p{font-size:12px;color:#385c48;margin-top:7px}.take-it-with-you details{border-top:1px solid #c4ddce;margin-top:12px;padding-top:10px}.take-it-with-you summary{font-size:12px;font-weight:800;cursor:pointer;line-height:1.5}
